const varint = () => {
  let v = 0, s = 0, b;
  do { b = bytes[i++]; v += (b & 0x7f) * 2 ** s; s += 7; } while (b & 0x80);
  return v;
};

const skip = wire => {
  if (wire === 0) varint();
  else if (wire === 1) i += 8;
  else if (wire === 2) i += varint();
  else if (wire === 5) i += 4;
};
